### GET /api/recent
```typescript
import { NextResponse } from "next/server"
import { getRecentActivities, getActivitiesByTier, getTotalCount } from "@/lib/db"
import type { LabelTier, ActivityLogEntry } from "@/lib/types"

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url)
  const limit = Math.min(Number(searchParams.get("limit") ?? 20), 100)
  const offset = Number(searchParams.get("offset") ?? 0)
  const tier = searchParams.get("tier") as LabelTier | "all" | null

  let activities: ActivityLogEntry[]
  let total: number

  if (tier && tier !== "all") {
    activities = getActivitiesByTier(tier as LabelTier, limit, offset)
    total = getTotalCount(tier as LabelTier)
  } else {
    activities = getRecentActivities(limit, offset)
    total = getTotalCount()
  }

  // Parse JSON strings in each entry before returning
  const parsed = activities.map(a => ({
    ...a,
    breakdown: JSON.parse(a.breakdown),
    testSignals: JSON.parse(a.testSignals),
  }))

  return NextResponse.json({ activities: parsed, total })
}
```

Returns: `{ activities: ActivityLogEntry[], total: number }` where breakdown and testSignals are parsed from JSON strings into objects/arrays.

**Important:** Clamp limit to max 100 to prevent abuse. Default limit=20, offset=0.

**Important:** Validate tier against known values before querying. If tier is invalid (not one of the 4 tiers or "all"), treat as "all".

