    labelerServer.start({ port: LABELER_PORT, host: HOST }, (err, address) => {
      if (err) { reject(err); return }
      logger.info({ address }, "LabelerServer started")
      resolve()
    })
  })

  // 2. Start metrics server (unchanged)
